function findKthLargest(nums, k) {
  const heap = [];   // min-heap holding the k largest values seen so far
  const swap = (a, b) => ([heap[a], heap[b]] = [heap[b], heap[a]]);
  const push = (x) => {
    heap.push(x);
    for (let i = heap.length - 1; i > 0 && heap[(i - 1) >> 1] > heap[i]; i = (i - 1) >> 1) swap(i, (i - 1) >> 1);
  };
  const popMin = () => {
    const last = heap.pop();
    if (heap.length === 0) return;
    heap[0] = last;
    for (let i = 0; ; ) {
      const l = 2 * i + 1, r = l + 1;
      let small = i;
      if (l < heap.length && heap[l] < heap[small]) small = l;
      if (r < heap.length && heap[r] < heap[small]) small = r;
      if (small === i) break;
      swap(i, small);
      i = small;
    }
  };
  for (const x of nums) {
    push(x);
    if (heap.length > k) popMin();   // drop the smallest: it can't be in the top k
  }
  return heap[0];   // the smallest of the k largest
}

