  let lo = 0, hi = nums.length - 1;
  while (true) {
    const pivot = nums[lo + Math.floor(Math.random() * (hi - lo + 1))];
    // Three zones: [lo, lt) bigger than pivot, [lt, gt] equal, (gt, hi] smaller.
    let lt = lo, i = lo, gt = hi;
    while (i <= gt) {
      if (nums[i] > pivot) {
        [nums[lt], nums[i]] = [nums[i], nums[lt]];
        lt++; i++;
      } else if (nums[i] < pivot) {
        [nums[i], nums[gt]] = [nums[gt], nums[i]];
        gt--;
      } else {
        i++;
      }
    }
    if (k - 1 < lt) hi = lt - 1;        // the answer is among the bigger values
    else if (k - 1 > gt) lo = gt + 1;   // ... or among the smaller ones
    else return pivot;                  // index k - 1 holds the pivot
  }
}

