class Solution {
    private final Random random = new Random();

    public int findKthLargest(int[] nums, int k) {
        int lo = 0, hi = nums.length - 1;
        while (true) {
            int pivot = nums[lo + random.nextInt(hi - lo + 1)];
            // Three zones: [lo, lt) bigger than pivot, [lt, gt] equal, (gt, hi] smaller.
            int lt = lo, i = lo, gt = hi;
            while (i <= gt) {
                if (nums[i] > pivot) swap(nums, lt++, i++);
                else if (nums[i] < pivot) swap(nums, i, gt--);
                else i++;
            }
            if (k - 1 < lt) hi = lt - 1;        // the answer is among the bigger values
            else if (k - 1 > gt) lo = gt + 1;   // ... or among the smaller ones
            else return pivot;                  // index k - 1 holds the pivot
        }
    }

    private void swap(int[] nums, int a, int b) {
        int t = nums[a];
        nums[a] = nums[b];
        nums[b] = t;
    }
}

